import pytest
from hypothesis import given, strategies as st, settings

import impl


@given(
    base=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False),
    cap=st.floats(min_value=1e-6, max_value=1e6, allow_nan=False, allow_infinity=False),
    attempts=st.integers(min_value=0, max_value=60),
)
@settings(max_examples=200)
def test_ceiling_matches_formula_property(base, cap, attempts):
    sched = impl.schedule(attempts, base, cap, lambda u: u)
    assert len(sched) == attempts
    for i, delay in enumerate(sched):
        expected_ceiling = min(cap, math.ldexp(base, i))
        assert math.isclose(delay, expected_ceiling, rel_tol=1e-9, abs_tol=1e-12), (i, delay, expected_ceiling)
        assert 0 <= delay <= cap + 1e-9
        assert math.isfinite(delay)
"}]}
